import { test, expect } from '@playwright/test';

test.describe('File Upload Queue', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should remove a file from the upload queue', async ({ page }) => {
    // Upload a file
    const fileInput = page.getByLabel('Upload File');
    await fileInput.setInputFiles('path/to/file.txt');

    // Verify the file is in the upload queue
    const uploadedFile = page.getByText('file.txt');
    await expect(uploadedFile).toBeVisible();

    // Remove the file from the upload queue
    const removeButton = uploadedFile.getByRole('button', { name: 'Remove' });
    await removeButton.click();

    // Verify the file is no longer in the upload queue
    await expect(uploadedFile).not.toBeVisible();
  });

  test('should not submit if the upload queue is empty', async ({ page }) => {
    // Attempt to submit without uploading a file
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify that an error message is displayed
    const errorMessage = page.getByText('No files to upload');
    await expect(errorMessage).toBeVisible();
  });
});
